csui.define('d2/utils/test/common.core.mock',[
  'nuc/lib/jquery',
  'nuc/lib/underscore',
  'nuc/lib/jquery.mockjax',
  'nuc/models/member',
  'nuc/models/actions',
  'dctmw/server.adaptors/converters/user',
  'dctmw/models/repositories',
  'dctmw/models/formats',
  'd2/models/table/dm.types.holder',
  'd2/utils/contexts/context.controller',
  'dctmw/utils/authenticators/auth.storage',
  'dctmw/utils/rest.resources',
  'd2/utils/server.query.utils',
  'd2/utils/node.utils',
  'dctmw/utils/utils',
  'd2/utils/constants',
  'd2/utils/widget.constants',
  'json!./startup.data.json'
], function ($, _, mockjax, MemberModel, ActionCollection, userConverter, RepositoryCollection, FormatCollection,
             DctmTypesHolder, D2ContextController, authStorage, RestResources, serverQueryUtils, nodeUtils, utils,
             constants, widgetConstants, mockData) {
  'use strict';

  var mocks = [];

  return {

    enable: function () {
      var authData = {};
      authData[constants.AuthStorage.REPOSITORY] = 'd2repo';
      authStorage.setCurrTabData(authData);
      utils.getLocalStore(constants.StorageKey.AUTH_DATA).set('authRepos', {'d2repo': true});

      spyOn(RestResources, 'getHomeDocLinks').and.returnValue(_.map(mockData.services.resources, function (entry, key) {
        return {
          rel: key,
          href: entry.href
        };
      }));

      spyOn(RestResources, 'getCurrentRepository').and.returnValue((new RepositoryCollection([mockData.repository])).at(0));
      
      var user = new MemberModel(userConverter.convertUser(mockData.currentuser));
      var defaultWidgets = mockData.defaultWidgets;
      user.set('_home_cabinet', {id: '0c0015fa80010809'});
      user.set('defaultWidgets', defaultWidgets);
      user.set('client_capability',2);
      user.set('preferences', {
        order_folder_before: true,
        links: [{
          href: '//server/d2/repositories/d2repo/d2-preferences/column-preferences',
          rel: 'http://identifiers.emc.com/linkrel/d2-column-preferences'
        }]
      });
      user.set('MenuActions', new ActionCollection(serverQueryUtils._parseActions({
        entries: [{
          id: '',
          content: {
            actionItems: mockData.userActions
          }
        }]
      }, 'user')['']));
      spyOn(RestResources, 'getCurrentUser').and.callFake(function () {
        return user;
      });

      spyOn(RestResources, 'getFormats').and.returnValue(new FormatCollection(mockData.formats.entries.map(function (entry) {
        return _.extend(_.pick(entry.content, 'is-default'),
          _.pick(entry.content.properties, 'name', 'r_object_id', 'mime_type', 'dos_extension', 'description', 'is_hidden'));
      })));

      spyOn(serverQueryUtils, '_fetchColumnDisplayInfo').and.callFake(function () {
        return $.Deferred().resolve({}).promise();
      });

      spyOn(RestResources, 'getDctmTypeData').and.returnValue(new DctmTypesHolder({
        'dm_sysobject': ['dm_document', 'dm_folder'],
        'dm_folder': ['dm_cabinet', 'dm_attachments_folder', 'dmc_module', 'dmc_java_library', 'dmc_workqueue_category',
          'dm_xml_application', 'dm_category', 'dmc_calendar', 'dmc_datatable', 'dmc_discussion',
          'dmc_room', 'dmc_topic', 'dm_attachment_folder'],
        'dmc_module': ['dmc_aspect_type', 'dmc_validation_module'],
        'dm_category': ['dm_taxonomy'],
        'dm_document': ['sam_doc1', 'sam_doc2']
      }, {
        'dm_folder': 'dm_sysobject',
        'dm_cabinet': 'dm_folder',
        'dm_attachments_folder': 'dm_folder',
        'dmc_module': 'dm_folder',
        'dmc_java_library': 'dm_folder',
        'dmc_workqueue_category': 'dm_folder',
        'dm_xml_application': 'dm_folder',
        'dm_category': 'dm_folder',
        'dmc_calendar': 'dm_folder',
        'dmc_datatable': 'dm_folder',
        'dmc_discussion': 'dm_folder',
        'dmc_room': 'dm_folder',
        'dmc_topic': 'dm_folder',
        'dm_attachment_folder': 'dm_folder',
        'dmc_aspect_type': 'dmc_module',
        'dmc_validation_module': 'dmc_module',
        'dm_taxonomy': 'dm_category',
        'dm_document': 'dm_sysobject',
        'sam_doc1': 'dm_document',
        'sam_doc2': 'dm_document'
      }, {
        'dm_sysobject': 'Sys Object',
        'dm_folder': 'Folder',
        'dm_cabinet': 'Cabinet',
        'dm_attachments_folder': 'Attachments Folder',
        'dmc_module': 'Module',
        'dmc_java_library': 'Java Library',
        'dmc_workqueue_category': 'Workqueue Category',
        'dm_xml_application': 'XML Application',
        'dm_category': 'Category',
        'dmc_calendar': 'Calendar',
        'dmc_datatable': 'Data Table',
        'dmc_discussion': 'Discussion',
        'dmc_room': 'Room',
        'dmc_topic': 'Discussion',
        'dm_attachment_folder': 'Attachment Folder',
        'dmc_aspect_type': 'Aspect Type',
        'dmc_validation_module': 'Validation Module',
        'dm_taxonomy': 'Taxonomy',
        'dm_document': 'Document',
        'sam_doc1': 'Sam Document 1',
        'sam_doc2': 'Sam Document 2'
      }));

      spyOn(D2ContextController, 'getWidgetInfo').and.returnValue({
        name: 'WG Doclist',
        type: widgetConstants.D2.DOCLIST
      });
      spyOn(D2ContextController, 'getBreadcrumbRoot').and.returnValue({
        root: constants.NodeId.REPOSITORY
      });
      spyOn(D2ContextController, 'setBreadcrumbRoot');

      var origNodeConfigMethod = nodeUtils.getNodeWidgetConfig;
      spyOn(nodeUtils, 'getNodeWidgetConfig').and.callFake(function (nodeId, widgetInfo) {
        if ((!widgetInfo.type || widgetInfo.type === widgetConstants.D2.DOCLIST)
          && (!widgetInfo.name || widgetInfo.name === 'WG Doclist')) {
          return {
            r_object_id: '080015fa80006323',
            object_name: 'WG Doclist',
            title: 'Enables full browsing and content-seeking capabilities. Displays results from searches.',
            widget_type: 'DoclistWidget',
            label_value: 'Document list',
            desc_value: 'Enables full browsing and content-seeking capabilities. Displays results from searches.',
            widgetParams: {
              is_breadcrumb_enabled: 'true'
            },
            columns: [
              'object_name',
              'title',
              'a_status',
              'r_modify_date',
              'r_modifier'
            ],
            applications: [
              'D2 4.x',
              'HR'
            ],
            getParam: function (p) {
              return this.widgetParams[p];
            }
          };
        }
        return origNodeConfigMethod.apply(this, arguments);
      });

      mocks.push(mockjax({
        url: '//server/d2/repositories/d2repo/folders/0b0015fa8001333f',
        responseText: mockData['parentNode']
      }));

      mocks.push(
        mockjax({
          url: '//server/d2/auth',
          responseText: {}
        })
      )
    },

    disable: function () {
      authStorage.removeCurrTabData();
      utils.getLocalStore(constants.StorageKey.AUTH_DATA).remove('authRepos');

      var mock;
      while ((mock = mocks.pop()) != null) {
        mockjax.clear(mock);
      }
    }

  };

});
